  "ИИ использует опубликованную версию при подготовке каждого ответа.": "ЖИ әр жауапты дайындағанда жарияланған нұсқаны пайдаланады.",
  "Включите ИИ-ответы для подключённого номера в разделе интеграций.": "Интеграциялар бөлімінде қосылған нөмір үшін ЖИ жауаптарын қосыңыз.",
