  "Ручная работа с клиентами, сделками и задачами. Без оплаты и подтверждения администратора.": "Клиенттермен, мәмілелермен және тапсырмалармен қолмен жұмыс істеу. Төлем мен әкімшінің растауы қажет емес.",
