  "Один продукт — четыре масштаба работы. CRM и BasQar Control доступны во всех тарифах. ИИ-менеджер: пробный режим в Free, включён в Business и Pro. Массовые рассылки доступны со Start.": "Бір өнім, жұмыс көлеміне сай төрт тариф. CRM және BasQar Control барлық тарифте қолжетімді. ЖИ-менеджер Free тарифінде сынақ режимінде ұсынылады, Business және Pro тарифтеріне кіреді. Жаппай хабарлама жіберу Start тарифінен бастап қолжетімді.",
  "1 AI-кредит ≈ одно стандартное AI-действие. Ресурсы обновляются каждый расчётный месяц, в том числе при оплате за год, и не переносятся. 100 AI-кредитов Free выдаются один раз, в том числе для ознакомления с ИИ-менеджером. AI-кредиты Start используются для BasQar Control и других доступных AI-действий; ИИ-менеджер в Start не входит. Стоимость услуг внешнего WhatsApp-провайдера не входит в тариф BasQar.": "1 ЖИ кредиті шамамен бір стандартты ЖИ әрекетіне тең. Ресурстар әр есептік айда, соның ішінде бір жылға төлегенде де жаңартылады және келесі айға көшірілмейді. Free тарифінің 100 ЖИ кредиті бір рет беріледі, оларды ЖИ-менеджермен танысуға да пайдалануға болады. Start тарифінің ЖИ кредиттері BasQar Control және басқа қолжетімді ЖИ әрекеттеріне жұмсалады; ЖИ-менеджер Start тарифіне кірмейді. Сыртқы WhatsApp провайдерінің қызмет ақысы BasQar тарифіне кірмейді.",
