  "Когда AI отвечает сам. Часовой пояс компании, не сервера. Пока включено «Круглосуточно», расписание новых заявок из вкладки «Новые заявки» не меняется.": "ЖИ қашан өзі жауап береді. Сервердің емес, компанияның уақыт белдеуі қолданылады. «Тәулік бойы» қосулы кезде «Жаңа өтінімдер» қойындысындағы кесте өзгермейді.",
  "Круглосуточно": "Тәулік бойы",
