  "Локальный АВР": "Жергілікті акт",
  "Форма Р-1 (приказ МФ РК № 562) для печати и архива. Excel и PDF собираются в CRM из того же бланка, без входа в ИС ЭСФ.": "Басып шығаруға және мұрағатқа арналған Р-1 нысаны (ҚР ҚМ № 562 бұйрығы). Excel және PDF файлдары ЭШФ АЖ жүйесіне кірмей, CRM ішінде бір үлгіден жасалады.",
  "Excel-файл АВР скачан": "Актінің Excel файлы жүктеп алынды",
  "Скачать Excel": "Excel жүктеп алу",
  "PDF-файл АВР скачан": "Актінің PDF файлы жүктеп алынды",
  "Скачать PDF": "PDF жүктеп алу",
  "Подписание в BasQar": "BasQar жүйесінде қол қою",
  "Исполнитель подписывает АВР своей ЭЦП, затем передаёт ссылку заказчику. Заказчик подписывает через NCALayer без регистрации в BasQar.": "Орындаушы актіге өз ЭЦҚ-сымен қол қойып, сілтемені тапсырыс берушіге жібереді. Тапсырыс беруші BasQar жүйесіне тіркелмей, NCALayer арқылы қол қояды.",
  "Выберите один способ подписания этого АВР: BasQar или ИС ЭСФ. Перед подписью проверьте скачанный PDF. После начала подписания содержание АВР фиксируется.": "Осы актіге қол қоюдың бір тәсілін таңдаңыз: BasQar немесе ЭШФ АЖ. Қол қоймас бұрын жүктеп алынған PDF файлын тексеріңіз. Қол қою басталғаннан кейін акт мазмұны өзгертілмейді.",
  "Для подписи зафиксирован один PDF. Реквизиты и содержание этой версии больше не изменяются.": "Қол қою үшін бір PDF файлы бекітілді. Осы нұсқаның деректемелері мен мазмұны енді өзгертілмейді.",
  "Подписать АВР в BasQar": "BasQar жүйесінде актіге қол қою",
  "Создать новую ссылку заказчику": "Тапсырыс берушіге жаңа сілтеме жасау",
  "Отправить на подпись клиенту": "Клиентке қол қоюға жіберу",
  "Обновить статус подписи": "Қол қою күйін жаңарту",
  "Отменить подпись и исправить АВР": "Қол қоюды тоқтатып, актіні түзету",
  "Заказчик отклонил АВР": "Тапсырыс беруші актіні қабылдамады",
  "Ссылка действует до": "Сілтеменің жарамдылық мерзімі:",
  ". Новая ссылка заменяет предыдущую.": ". Жаңа сілтеме алдыңғы сілтемені алмастырады.",
  "Ссылка для заказчика": "Тапсырыс берушіге арналған сілтеме",
  "Ссылка скопирована": "Сілтеме көшірілді",
  "Открыть страницу подписания": "Қол қою бетін ашу",
  "Подписание и отправка в ИС ЭСФ": "ЭШФ АЖ жүйесінде қол қою және жіберу",
  "Проверьте реквизиты и позиции выше. Отправка в ИС ЭСФ начинается только после нажатия «Подписать и отправить АВР» на этой странице.": "Жоғарыдағы деректемелер мен тармақтарды тексеріңіз. ЭШФ АЖ жүйесіне жіберу осы беттегі «Актіге қол қою және жіберу» түймесін басқаннан кейін ғана басталады.",
  "На тестовом стенде используйте свои действующие ключи НУЦ: ключ для входа и ключ подписи организации. Демо-ключи из SDK ЭСФ принадлежат чужому БИН и для вашей организации не подойдут.": "Сынақ ортасында өзіңіздің қолданыстағы ҰКО кілттеріңізді пайдаланыңыз: кіру кілті және ұйымның қол қою кілті. ЭШФ SDK демо кілттері басқа БСН-ге тиесілі және ұйымыңызға жарамайды.",
  "NCALayer подключён": "NCALayer қосылды",
  "NCALayer подключится при нажатии «Подписать и отправить АВР»": "«Актіге қол қою және жіберу» түймесін басқанда NCALayer қосылады",
