  "Пароль кабинета ИС ЭСФ": "ЭШФ АЖ кабинетінің құпиясөзі",
  "Используется только для входа в ИС ЭСФ и не сохраняется. PIN ЭЦП вводится в NCALayer.": "Тек ЭШФ АЖ жүйесіне кіру үшін пайдаланылады және сақталмайды. ЭЦҚ PIN-коды NCALayer ішінде енгізіледі.",
