  "Никого не нашли. Попробуйте другой запрос или вкладку «Список номеров».": "Ешкім табылмады. Басқа сұрау енгізіңіз немесе «Нөмірлер тізімі» қойындысын ашыңыз.",
  "Загрузка клиентов…": "Клиенттер жүктелуде…",
  "В CRM пока нет клиентов для выбора.": "CRM жүйесінде таңдауға болатын клиенттер әзірге жоқ.",
  "Что делать с новыми контактами?": "Жаңа контактілермен не істеу керек?",
