  "Сообщение": "Хабарлама",
  "Сформировать с AI": "ЖИ көмегімен дайындау",
  "Написать вручную": "Қолмен жазу",
  "Без текста — только файл": "Мәтінсіз — тек файл",
  "Что сделать клиентам, например: уточнить удобное время для созвона": "Клиенттер үшін не істеу керек, мысалы: қоңырауға қолайлы уақытты нақтылау",
  "{{firstName}}, добрый день! ...": "{{firstName}}, қайырлы күн! ...",
  "Сгенерировать черновик": "Хабарлама жобасын жасау",
  "Это задача для CRM, не текст в WhatsApp. В письмо пойдёт смысл команды, а факты — из заявки, без копирования приказа и без выдуманных цен.": "Бұл — WhatsApp хабарламасының мәтіні емес, CRM тапсырмасы. Хатта пәрменнің мәні мен өтінімдегі нақты деректер қолданылады. Пәрмен сол күйі көшірілмейді, бағалар ойдан қосылмайды.",
  "Переменные: {{firstName}}, {{companyName}}, {{service}}, {{managerName}}. Пустое имя не даст «, добрый день!».": "Айнымалылар: {{firstName}}, {{companyName}}, {{service}}, {{managerName}}. Аты бос болса, «, қайырлы күн!» түріндегі артық үтір қойылмайды.",
  "Составить разное предложение каждому получателю": "Әр алушыға жеке ұсыныс дайындау",
  "CRM возьмёт суть вашей команды и подставит факты заявки: имя, что просил клиент, компания. Цены, скидки и сроки не выдумываем.": "CRM пәрменіңіздің мәнін пайдаланып, өтінімдегі нақты деректерді қосады: аты, клиент сұранысы, компаниясы. Баға, жеңілдік және мерзім ойдан қосылмайды.",
  "Пересобрать предложения": "Ұсыныстарды қайта дайындау",
  "Составить предложения из задачи": "Тапсырма негізінде ұсыныстар дайындау",
  "Сначала подготовьте черновик — кнопка станет активной.": "Алдымен хабарлама жобасын дайындаңыз — содан кейін түйме белсенді болады.",
  "Контакт": "Байланыс тұлғасы",
  "Отправим только вложения — убедитесь, что канал это позволяет.": "Тек тіркемелер жіберіледі — арнаның бұған мүмкіндік беретініне көз жеткізіңіз.",
