  "Пустые реквизиты вашей организации будут заполнены данными этой стороны. Заполненные значения сохранятся. При несовпадении БИН перенос не выполняется.": "Ұйымыңыздың бос деректемелері осы тараптың деректерімен толтырылады. Толтырылған мәндер сақталады. БСН сәйкес келмесе, деректер көшірілмейді.",
