  "Найдено несколько карточек с этим БИН / ИИН. Уточните дубли в разделе «Компании».": "Осы БСН / ЖСН бойынша бірнеше карточка табылды. «Компаниялар» бөліміндегі қайталанатын жазбаларды тексеріңіз.",
  "Этой компании ещё нет в справочнике. Сохраните карточку — договор можно будет сразу привязать к ней.": "Бұл компания анықтамалықта әлі жоқ. Карточканы сақтаңыз — шартты бірден онымен байланыстыруға болады.",
  "Сохранить компанию": "Компанияны сақтау",
  "Компания сопоставляется по БИН. В существующей карточке заполняются только пустые реквизиты.": "Компания БСН бойынша сәйкестендіріледі. Бар карточкада тек бос деректемелер толтырылады.",
  "Компания определяется по БИН / ИИН. Если у сделки ещё нет компании, заказчик будет привязан при сохранении. Реквизиты существующей компании сохранятся.": "Компания БСН / ЖСН бойынша анықталады. Мәміледе компания әлі болмаса, тапсырыс беруші сақтау кезінде байланыстырылады. Бар компанияның деректемелері сақталады.",
  "Пустые реквизиты вашей организации будут заполнены данными исполнителя. Заполненные значения сохранятся. При несовпадении БИН перенос не выполняется.": "Ұйымыңыздың бос деректемелері орындаушы деректерімен толтырылады. Толтырылған мәндер сақталады. БСН сәйкес келмесе, деректер көшірілмейді.",
