  "Instagram Direct и Meta Lead Forms": "Instagram Direct және Meta Lead Forms",
  "Подключение через страницу Facebook и токен приложения Meta. Для Instagram нужен привязанный профессиональный аккаунт. Для внешних клиентов приложение должно иметь необходимые разрешения Meta.": "Facebook парақшасы мен Meta қолданбасының токені арқылы қосылу. Instagram үшін байланыстырылған кәсіби аккаунт қажет. Сыртқы клиенттермен жұмыс істеу үшін қолданбада Meta-ның тиісті рұқсаттары болуы керек.",
