  "Verify Token (показывается сейчас)": "Verify Token (қазір көрсетіледі)",
  "Для Instagram выберите объект Instagram и поле messages; для форм — объект Page и leadgen. Сохраните проверку в Meta, затем включите подключение ниже. Не заменяйте callback, который обслуживает другую компанию.": "Instagram үшін Instagram нысаны мен messages өрісін, нысандар үшін Page нысаны мен leadgen өрісін таңдаңыз. Meta ішінде тексеруді сақтап, төмендегі қосылымды қосыңыз. Басқа компанияға қызмет көрсететін callback мекенжайын алмастырмаңыз.",
  "Отключено": "Ажыратылған",
