  "Приём в CRM отключён. История сохранена. При необходимости удалите подписку и в приложении Meta.": "CRM жүйесіне қабылдау өшірілді. Тарих сақталды. Қажет болса, Meta қолданбасындағы жазылымды да жойыңыз.",
  "Instagram: входящие сообщения и текстовые ответы в пределах 24 часов после сообщения клиента. Вложения открывайте в Instagram. Формы Meta создают заявки; обращения без телефона сохраняются для уточнения.": "Instagram: клиент хабарламасынан кейінгі 24 сағат ішінде кіріс хабарламалар мен мәтіндік жауаптар. Тіркемелерді Instagram ішінде ашыңыз. Meta нысандары өтінім жасайды; телефонсыз өтініштер нақтылау үшін сақталады.",
