  "После сохранения будет создана ссылка приглашения. Статус: «Ссылка создана», без отправки email.": "Сақтағаннан кейін шақыру сілтемесі жасалады. Күйі: «Сілтеме жасалды», email жіберілмейді.",
  "Промт и база знаний WhatsApp AI этой компании хранятся здесь. Клиенты CRM их не редактируют. Зелёный статус значит, что бот уже отвечает по этим текстам. Если статус жёлтый — в админке сохранено, в WhatsApp ещё нет.": "Осы компанияның WhatsApp ЖИ нұсқаулығы мен білім қоры осында сақталады. CRM клиенттері оларды өзгерте алмайды. Жасыл белгі боттың осы мәтіндерге сүйеніп жауап беретінін білдіреді. Сары белгі мәтіндердің әкімші панелінде сақталғанын, бірақ WhatsApp-та әлі қолданылмайтынын білдіреді.",
  "Материалов в базе:": "Базадағы материалдар:",
