  "Отправить в WhatsApp": "WhatsApp жүйесіне жіберу",
  "Как бот представляется, как здоровается, что можно обещать и чего нельзя. Юридический тон и стиль — тоже здесь.": "Бот өзін қалай таныстырады, қалай амандасады, нені уәде ете алады және нені уәде етпеуі керек. Заңдық тұжырымдары мен сөйлеу мәнері де осында беріледі.",
  "Текст промта": "ЖИ нұсқаулығының мәтіні",
  "Например: ты менеджер компании… отвечай коротко… цены только из базы знаний…": "Мысалы: сен компания менеджерісің… қысқа жауап бер… бағаларды тек білім қорынан ал…",
