  "В Tilda откройте «Настройки сайта» → «Формы» → «Webhook».": "Tilda ішінде «Сайт баптаулары» → «Нысандар» → «Webhook» бөлімін ашыңыз.",
  "Вставьте адрес для приёма заявок и сохраните. При запросе назначьте webhook формам сайта.": "Өтінім қабылдау мекенжайын енгізіп, сақтаңыз. Сұралса, webhook мекенжайын сайт нысандарына тағайындаңыз.",
  "Если webhook не назначен сразу — в редакторе страницы откройте блок формы, в Content включите WEBHOOK и опубликуйте страницу.": "Webhook бірден тағайындалмаса, бет редакторында нысан блогын ашып, Content ішінде WEBHOOK қосыңыз да, бетті жариялаңыз.",
  "Стандартные поля Tilda": "Tilda стандартты өрістері",
  "принимаются как есть. Имя и телефон обязательны.": "өзгеріссіз қабылданады. Аты мен телефоны міндетті.",
  "Отправьте заявку с опубликованной формы. Tilda шлёт": "Жарияланған нысаннан өтінім жіберіңіз. Tilda жіберетін формат:",
