  "С внешнего сайта отправьте JSON на адрес компании. Ключ CRM в HTML размещать не нужно.": "Сыртқы сайттан компания мекенжайына JSON жіберіңіз. CRM кілтін HTML ішіне орналастыру қажет емес.",
