  "Выбрать другого клиента для задачи": "Тапсырма үшін басқа клиент таңдау",
  "Найти клиентов по выбранным условиям": "Таңдалған шарттар бойынша клиенттерді табу",
  "Убрать вложение из подготовленного сообщения": "Дайын хабарламадан тіркемені алып тастау",
  "Закрыть выбор следующего шага без создания задачи": "Тапсырма жасамай, келесі әрекетті таңдау терезесін жабу",
