  "ИС ЭСФ не приняла сертификат для входа. На тестовом стенде используйте свой действующий ключ НУЦ для входа, не ключ подписи. Организация должна быть зарегистрирована на test3.esf.kgd.gov.kz.": "ЭШФ АЖ кіру сертификатын қабылдамады. Сынақ ортасында қол қою кілтін емес, өзіңіздің қолданыстағы ҰКО кіру кілтін пайдаланыңыз. Ұйым test3.esf.kgd.gov.kz сайтында тіркелген болуы керек.",
