  "Встречи CRM передаются в Google Calendar. Переносы обновляют события, отмены удаляют их. События, созданные вручную в Google, в CRM не импортируются.": "CRM кездесулері Google Calendar жүйесіне жіберіледі. Ауыстыру оқиғаларды жаңартады, тоқтату оларды жояды. Google ішінде қолмен жасалған оқиғалар CRM жүйесіне импортталмайды.",
  "Новые ответы формы становятся заявками. Если нет телефона, обращение поступает в очередь уточнения. Поля можно сопоставить после подключения.": "Нысанның жаңа жауаптары өтінімге айналады. Телефон болмаса, өтініш нақтылау кезегіне түседі. Қосылғаннан кейін өрістерді сәйкестендіруге болады.",
  "Новые входящие письма Gmail и поддерживаемые вложения появляются в диалогах. Ответы отправляйте из Gmail; автоматические заявки из писем не создаются.": "Жаңа Gmail кіріс хаттары мен қолдау көрсетілетін тіркемелер диалогтарда пайда болады. Жауаптарды Gmail арқылы жіберіңіз; хаттардан автоматты өтінімдер жасалмайды.",
